#!/usr/bin/env bash
# =============================================================================
# =============================================================================
# InstantGram v1.19.4  -  Analytics in the Me screen
#   * NEW: an Analytics button on your own profile opens the numbers:
#         Overview    views, accounts reached, engagement, new followers,
#                     a views-per-day chart and your best posts
#         Reach       accounts reached, reach rate, followers vs newcomers,
#                     most reached posts
#         Engagement  likes, comments, shares, reposts, engagement rate,
#                     averages per post, most engaging posts
#         Audience    followers, new followers, countries, languages,
#                     followers vs everybody else
#   * 7, 30 or 90 days, switched with one tap. Tapping a post opens it.
#   * No new service and nothing to set up: the numbers come from what the app
#     already writes (view documents, post counters, followers). They start today,
#     so older posts only carry what was counted from now on.
#   * Reads are capped (60 posts, 300 views each, 120 profiles) so it stays quick.
#   * The rows of "Best performers" sit in their own Material, so the tap ripple is
#     not hidden behind the card (newer Flutter checks this in debug mode).
# Run from the project root:   bash update_v1194_analytics.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="41d552c6ec133f7c85399fef898658676bf5ac1256ee67a427a2d3c64f6f590a"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/services/online_music_service.dart ] || { echo "ERROR: the free music update is not installed. Run update_v1171_free_music.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
awk '/^__PAYLOAD__$/{f=1;next} f' "$0" | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       Download it again and retry."
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
chmod +x tools/merge_audio.sh signer/setup.sh 2>/dev/null || true
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
echo "Done. v1.19.4 is in place."
echo ""
echo "Good to know:"
echo "  * Me screen > Analytics (only on your own profile)."
echo "  * Nothing to set up and nothing to deploy."
echo "  * The numbers start from today: they are counted from the view documents the"
echo "    app writes, and those begin with this version."
exit 0

